sys_script.script:
/**
 * ESR - Workflow validation
 * Before / Insert + Update / Order 250
 *
 * Gates:
 *   -> 4 On Hold     requires On Hold Reason AND Work Notes
 *   -> 5 Resolved    requires Resolution Notes AND Resolution Code
 *   5 -> 3 Reopen    requires Reopen Reason
 *   -> 6 Closed      only from Resolved, manager/admin only
 *   state 6          frozen for non-privileged users
 */

(function validateTicketWorkflow(current, previous) {

    var isInsert = current.operation() === 'insert';

    var state = current.getValue('state');
    var previousState = (!isInsert && previous)
        ? previous.getValue('state')
        : '';

    var stateChanged = isInsert || state !== previousState;

    var isPrivileged =
        gs.hasRole('x_412993_employe_1.manager') ||
        gs.hasRole('admin');

    function reject(message) {
        gs.addErrorMessage(message);
        current.setAbortAction(true);
    }

    /* =========================================================
       CLOSED TICKET PROTECTION
       ========================================================= */

    if (!isInsert && previousState === '6' && !isPrivileged) {

        reject(
            'This ticket is closed and can no longer be modified. Ask a manager to reopen it, or raise a new ticket.'
        );

        return;
    }

    /* =========================================================
       ON HOLD VALIDATION
       Requires BOTH On Hold Reason and Work Notes
       ========================================================= */

    if (stateChanged && state === '4') {

        if (!current.getValue('on_hold_reason')) {

            reject(
                'Select an On Hold Reason before placing this ticket on hold.'
            );

            return;
        }

        if (current.work_notes.nil()) {

            reject(
                'Enter Work Notes explaining why this ticket is being placed on hold.'
            );

            return;
        }
    }

    /* =========================================================
       RESOLUTION VALIDATION
       ========================================================= */

    if (stateChanged && state === '5') {

        if (!current.getValue('resolution_notes')) {

            reject(
                'Resolution Notes are mandatory before a ticket can be resolved. Describe what was done to fix it.'
            );

            return;
        }

        if (!current.getValue('resolution_code')) {

            reject(
                'Select a Resolution Code before resolving this ticket.'
            );

            return;
        }
    }

    /* =========================================================
       REOPEN VALIDATION
       ========================================================= */

    if (
        !isInsert &&
        previousState === '5' &&
        state === '3' &&
        !current.getValue('reopen_reason')
    ) {

        reject(
            'Enter a Reopen Reason explaining why this ticket is not resolved before reopening it.'
        );

        return;
    }

    /* =========================================================
       CLOSURE VALIDATION
       ========================================================= */

    if (stateChanged && state === '6') {

        if (isInsert || previousState !== '5') {

            reject(
                'A ticket can only be closed from the Resolved state. Resolve it first, then close it.'
            );

            return;
        }

        if (!isPrivileged) {

            reject(
                'Only a manager can close a resolved ticket.'
            );

            return;
        }
    }

})(current, previous);
